INSERT INTO definitions(definition_number,section_id,title,definition_text,formal_latex,word_latex,provenance,source_id,assumptions,notes,validation_status,created_revision_id) SELECT '3.2.26',@section_id,'Eigenvektor und Eigenwert','Ein von null verschiedener Vektor v heißt Eigenvektor eines linearen Operators T, wenn T(v)=λv gilt. λ heißt Eigenwert.','T(v)=\\lambda v','T(v)=\\lambda v','adapted',(SELECT source_id FROM sources WHERE citation_number=71 LIMIT 1),'Lineare Operatoren und endlichdimensionale Vektorräume sind definiert.','Etablierte lineare Algebra; keine FRZK-spezifische Eigenleistung.','verified',@revision_id WHERE NOT EXISTS(SELECT 1 FROM definitions WHERE definition_number='3.2.26');
INSERT INTO definitions(definition_number,section_id,title,definition_text,formal_latex,word_latex,provenance,source_id,assumptions,notes,validation_status,created_revision_id) SELECT '3.2.27',@section_id,'Charakteristisches Polynom','Das charakteristische Polynom einer quadratischen Matrix A ist p_A(λ)=det(A-λI). Seine Nullstellen sind die Eigenwerte.','p_A(\\lambda)=\\det(A-\\lambda I)','p_A(\\lambda)=\\det(A-\\lambda I)','adapted',(SELECT source_id FROM sources WHERE citation_number=71 LIMIT 1),'Lineare Operatoren und endlichdimensionale Vektorräume sind definiert.','Etablierte lineare Algebra; keine FRZK-spezifische Eigenleistung.','verified',@revision_id WHERE NOT EXISTS(SELECT 1 FROM definitions WHERE definition_number='3.2.27');
INSERT INTO definitions(definition_number,section_id,title,definition_text,formal_latex,word_latex,provenance,source_id,assumptions,notes,validation_status,created_revision_id) SELECT '3.2.28',@section_id,'Eigenraum','Der Eigenraum zu λ ist der Kern von A-λI und enthält den Nullvektor sowie alle zu λ gehörenden Eigenvektoren.','E_\\lambda=\\ker(A-\\lambda I)','E_\\lambda=\\ker(A-\\lambda I)','adapted',(SELECT source_id FROM sources WHERE citation_number=71 LIMIT 1),'Lineare Operatoren und endlichdimensionale Vektorräume sind definiert.','Etablierte lineare Algebra; keine FRZK-spezifische Eigenleistung.','verified',@revision_id WHERE NOT EXISTS(SELECT 1 FROM definitions WHERE definition_number='3.2.28');
