INSERT INTO source_usage(source_id,section_id,usage_type,claim_summary,exact_location,is_first_mention,citation_checked,notes,created_revision_id) SELECT s.source_id,@section_id,CASE WHEN s.citation_number=74 THEN 'example' WHEN s.citation_number=76 THEN 'theory' ELSE 'definition' END,CASE s.citation_number WHEN 71 THEN 'Grundlagen zu Eigenwerten, Eigenvektoren, Eigenräumen und charakteristischem Polynom.' WHEN 74 THEN 'Geometrische Interpretation und Rechenbeispiele.' WHEN 76 THEN 'Operatorentheoretische Einordnung, Vielfachheiten und Spektrum.' WHEN 82 THEN 'Abstrakte Einordnung linearer Operatoren.' END,'Abschnitt 3.2.10',0,1,CONCAT('Wiederverwendung der Literaturstelle [',s.citation_number,'].') ,@revision_id FROM sources s WHERE s.citation_number IN(71,74,76,82) AND NOT EXISTS(SELECT 1 FROM source_usage su WHERE su.source_id=s.source_id AND su.section_id=@section_id);
