-- FRZK-Repository-Update 3.2.10
START TRANSACTION;
SET @parent_section_id := (SELECT section_id FROM dissertation_sections WHERE section_code='3.2' LIMIT 1);
SET @parent_revision_id := (SELECT revision_id FROM repository_revisions WHERE revision_code='RKB-NEU-K3.2.9-V1' LIMIT 1);
SELECT 'RKB-NEU-K3.2.10-V1',NOW(),'section','3.2.10','3.2.10-v1','Abschnitt 3.2.10 mit Definitionen 3.2.26 bis 3.2.28 und Gleichungen (3.229) bis (3.271).','Olaf Thiele / ChatGPT',@parent_revision_id
WHERE @parent_section_id IS NOT NULL AND @parent_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM repository_revisions WHERE revision_code='RKB-NEU-K3.2.10-V1');
SET @revision_id := (SELECT revision_id FROM repository_revisions WHERE revision_code='RKB-NEU-K3.2.10-V1' LIMIT 1);
SELECT @parent_section_id,'3.2.10','Eigenwerte und Eigenvektoren linearer Operatoren',3,3.21000,'final',0,'Definitionen 3.2.26 bis 3.2.28; Gleichungen (3.229) bis (3.271); Quellen [71], [74], [76], [82].'
WHERE NOT EXISTS(SELECT 1 FROM dissertation_sections WHERE section_code='3.2.10');
SET @section_id := (SELECT section_id FROM dissertation_sections WHERE section_code='3.2.10' LIMIT 1);
UPDATE dissertation_sections SET parent_section_id=@parent_section_id,title='Eigenwerte und Eigenvektoren linearer Operatoren',chapter_no=3,section_order=3.21000,status='final',is_original_contribution=0,notes='Definitionen 3.2.26 bis 3.2.28; Gleichungen (3.229) bis (3.271); Quellen [71], [74], [76], [82].' WHERE section_id=@section_id;
COMMIT;
SELECT @revision_id revision_id,@section_id section_id,(SELECT COUNT(*) FROM definitions WHERE section_id=@section_id) definitions_count,(SELECT COUNT(*) FROM equations WHERE section_id=@section_id) equations_count,(SELECT COUNT(*) FROM source_usage WHERE section_id=@section_id) source_usage_count,(SELECT counter_value FROM repository_counters WHERE counter_key='next_definition_number') next_definition_number,(SELECT counter_value FROM repository_counters WHERE counter_key='next_equation_number') next_equation_number,(SELECT counter_value FROM repository_counters WHERE counter_key='next_citation_number') next_citation_number;
